import fs from 'fs';
import path from 'path';
import type { Configuration, RuleSetRule } from 'webpack';
import { merge } from 'webpack-merge';

import grafanaConfig, { type Env } from './.config/webpack/webpack.config';

const BROWSERSLIST_FILE = path.resolve(process.cwd(), '.browserslistrc');

type SwcLoaderOptions = {
  env?: Record<string, unknown>;
  jsc?: {
    target?: string;
    transform?: {
      react?: { development?: boolean };
    };
  };
};

/**
 * Find the swc-loader options in the scaffolded config from `.config/webpack/webpack.config.ts`.
 *
 * That file is generated by `@grafana/create-plugin` and there's no hook for changing the swc
 * options, so the only way to adjust them is to reach into the rule and edit it in place. If the
 * rule ever moves or gets renamed we want the build to stop rather than quietly skip the edits
 * below — swc falls all the way back to es3 when nothing sets a target.
 */
const getSwcLoaderOptions = (config: Configuration): SwcLoaderOptions => {
  const rules = (config.module?.rules ?? []) as RuleSetRule[];

  for (const rule of rules) {
    if (typeof rule !== 'object' || rule == null) {
      continue;
    }

    if (rule.use && typeof rule.use === 'object' && 'loader' in rule.use && rule.use.loader === 'swc-loader') {
      const options = rule.use.options as SwcLoaderOptions | undefined;
      if (options?.jsc) {
        return options;
      }
    }
  }

  throw new Error(
    'Could not find the swc-loader rule in the scaffolded webpack config. ' +
      'It probably changed shape in a newer @grafana/create-plugin — check the overrides in webpack.config.ts.'
  );
};

/**
 * Derive the compile target from `.browserslistrc` instead of the fixed `jsc.target: 'es2015'`
 * that `.config/webpack/webpack.config.ts` sets.
 *
 * grafana/grafana does the same thing for its own bundle (`scripts/webpack/rules.ts` feeds
 * `browserslist()` into esbuild), and a plugin only ever has to run in the browsers Grafana
 * supports — so pinning a fixed, much older ES version just means shipping transpiler polyfills
 * nobody needs. One of those polyfills (the one for named capture groups) was behind routes
 * failing to save with "Invalid duration format".
 *
 * swc rejects `env` and `jsc.target` together, so the target has to be removed first. Leaving
 * `env.targets` unset is what makes swc read the browser list on its own — we don't have to
 * resolve it ourselves.
 *
 * `env.path` is where swc looks for `.browserslistrc`, and it defaults to the current working
 * directory rather than searching upwards from each source file. So a build started from a
 * subdirectory would find no list and silently fall back to browserslist's own defaults, which
 * are much older than ours. Passing the path explicitly and checking the file is there turns
 * that into an error instead of a different bundle.
 */
const applyBrowserslistTarget = (options: SwcLoaderOptions) => {
  if (!fs.existsSync(BROWSERSLIST_FILE)) {
    throw new Error(
      `Expected a browser list at ${BROWSERSLIST_FILE}, but it isn't there. ` +
        'Without it swc would compile against its own default browser list instead of the ' +
        'browsers Grafana supports. Run the build from the repository root.'
    );
  }

  delete options.jsc?.target;
  options.env = { path: process.cwd() };
};

const applyReactDevRuntimeException = (options: SwcLoaderOptions) => {
  const react = options.jsc?.transform?.react;
  if (!react) {
    throw new Error(
      'Could not find the swc React transform options to disable the dev JSX runtime. ' +
        'Check the overrides in webpack.config.ts against the scaffolded config.'
    );
  }

  // Force non-dev JSX output to keep compatibility with React 18 runtimes.
  react.development = false;
};

const config = async (env: Env): Promise<Configuration> => {
  const baseConfig = await grafanaConfig(env);
  const swcLoaderOptions = getSwcLoaderOptions(baseConfig);

  applyBrowserslistTarget(swcLoaderOptions);

  if (env.development) {
    applyReactDevRuntimeException(swcLoaderOptions);
  }

  return merge(baseConfig, {
    // The scaffolded config caches builds on disk, but only watches its own file for changes.
    // Editing the browser list changes what swc emits, so it has to invalidate the cache too —
    // otherwise you keep getting modules compiled for the previous list. The key has to differ
    // from the scaffold's own ("config") so this adds to the list instead of replacing it.
    cache: {
      buildDependencies: {
        browserslist: [BROWSERSLIST_FILE],
      },
    },

    // Externalize react/jsx-runtime for React 19 compatibility
    // Required to prevent __SECRET_INTERNALS crashes with @tanstack/react-query
    // See: https://grafana.com/blog/2025/01/22/react-19-is-coming-to-grafana-what-plugin-developers-need-to-know/
    // Requires Grafana >= 12.3.0
    externals: ['react/jsx-runtime', 'react/jsx-dev-runtime'],
  });
};

export default config;
